krb5_error_code prepare_reprocessed_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;
    krb5_principal new_server = NULL;
    krb5_data *realm = NULL;

    if (request->flags & KDC_OPT_CANONICALIZE) {
        /* Check if server principal is a service principal for krbtgt */
        if (krb5_principal_compare_any_realm(request->context, *krbtgt_princ, request->server)) {
            /* Attempt to canonicalize the server principal */
            ret = krb5_unparse_name(request->context, *krbtgt_princ, &realm);
            if (ret)
                return ret;

            /* Map the FQDN to a realm and construct a cross-realm TGT */
            ret = krb5_build_principal_ext(request->context, &new_server,
                                           realm->length, realm->data,
                                           0, NULL, NULL);
            if (ret) {
                krb5_free_data(request->context, realm);
                return ret;
            }

            /* Modify the request with the new principal */
            krb5_free_principal(request->context, request->server);
            request->server = new_server;
        }
    }

    return ret;
}

krb5_error_code prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;
    krb5_data *realm = NULL;

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        if (krbtgt_princ && krb5_princ_type(krbtgt_princ) == KRB5_PRINC_NAME_SRV) {
            const char *fqdn = krb5_principal_get_comp_string(krbtgt_princ, 0);

            ret = krb5_get_realm_from_fqdn(NULL, fqdn, &realm);
            if (ret != 0) {
                return ret;
            }

            if (realm != NULL) {
                krb5_principal new_server_princ;
                ret = krb5_build_principal_simple(NULL, &new_server_princ,
                                                  realm->length, realm->data,
                                                  0);
                if (ret != 0) {
                    krb5_free_data(NULL, realm);
                    return ret;
                }

                /* Modify the request with the new server principal */
                krb5_free_principal(NULL, request->server);
                request->server = new_server_princ;
                request->kdc_options &= ~KDC_OPT_CANONICALIZE;
            }
        }
    }

    return ret;
}

krb5_error_code prepare_kdc_request_for_reprocessing(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;
    krb5_context context = NULL;
    krb5_principal server_princ = NULL;
    char *fqdn = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_INVALID_REQUEST;
    }

    if ((request->kdc_options & KDC_OPT_CANONICALIZE) == 0) {
        return 0;
    }

    ret = krb5_init_context(&context);
    if (ret) {
        return ret;
    }

    server_princ = *krbtgt_princ;

    ret = krb5_unparse_name(context, server_princ, &fqdn);
    if (ret) {
        goto cleanup;
    }

    ret = krb5_build_principal_ext(context, krbtgt_princ, 0, NULL, NULL);
    if (ret) {
        goto cleanup;
    }

    ret = krb5_free_unparsed_name(context, fqdn);
    if (ret) {
        goto cleanup;
    }

cleanup:
    if (context) {
        krb5_free_context(context);
    }

    return ret;
}

krb5_error_code prepare_kdc_request_for_reprocessing(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;
    krb5_data *server_name = NULL;
    krb5_principal new_server_princ = NULL;

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        server_name = krb5_principal_get_name(NULL, *krbtgt_princ);
        if (!server_name || server_name->length == 0) {
            ret = KRB5_KDCREP_ERR_MODIFIED;
            goto cleanup;
        }

        /* Attempt to map the server's FQDN to a realm */
        krb5_realm *mapped_realm = krb5_map_fqdn_to_realm(server_name->data);
        if (!mapped_realm) {
            ret = KRB5_KDCREP_ERR_MODIFIED;
            goto cleanup;
        }

        /* Construct a new cross-realm TGT principal */
        ret = krb5_build_cross_realm_tgt_principal(&new_server_princ, server_name->data, mapped_realm);
        if (ret != 0) {
            goto cleanup;
        }

        /* Free the original principal */
        krb5_free_principal(NULL, *krbtgt_princ);

        *krbtgt_princ = new_server_princ;
    }

cleanup:
    if (server_name) {
        krb5_data_free(server_name);
    }

    return ret;
}

krb5_error_code prepare_kdc_request_for_reprocessing(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;
    krb5_principal server_princ = NULL;
    krb5_data *realm = NULL;

    if ((request->flags & KDC_OPT_CANONICALIZE) == 0) {
        return 0;
    }

    server_princ = request->client;

    if (!server_princ || server_princ->type != KRB5_PRINCIPAL_TYPE_SRV) {
        return KRB5KDC_ERR_BAD_SERVER;
    }

    ret = krb5_unparse_name(krb5_context, server_princ, &realm);
    if (ret) {
        return ret;
    }

    if (krb5_is_fqdn_in_realm(krb5_context, realm, NULL)) {
        ret = krb5_build_cross_realm_tgt(krb5_context, realm, krbtgt_princ, &request->client);
        if (ret) {
            krb5_free_unparsed_name(krb5_context, realm);
            return ret;
        }

        request->flags |= KDC_OPT_CROSS_REALM;
    }

    krb5_free_unparsed_name(krb5_context, realm);
    return 0;
}
